/**
 * Lightweight in-memory ZIP file creator (PKZIP format)
 * Không cần thư viện ngoài, hỗ trợ đóng gói nhanh hàng loạt video và tải về.
 */

function createCrcTable() {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let k = 0; k < 8; k++) {
            c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
        }
        table[i] = c;
    }
    return table;
}

const CRC_TABLE = createCrcTable();

function crc32(buffer) {
    let crc = 0xFFFFFFFF;
    const bytes = new Uint8Array(buffer);
    for (let i = 0; i < bytes.length; i++) {
        crc = CRC_TABLE[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

export async function createZipBlob(files = []) {
    // files: Array of { name: string, data: Blob | ArrayBuffer | Uint8Array }
    const fileEntries = [];
    let offset = 0;

    const parts = [];

    for (const file of files) {
        let buffer;
        if (file.data instanceof Blob) {
            buffer = await file.data.arrayBuffer();
        } else if (file.data instanceof Uint8Array) {
            buffer = file.data.buffer;
        } else {
            buffer = file.data;
        }

        const uint8 = new Uint8Array(buffer);
        const nameBytes = new TextEncoder().encode(file.name);
        const crc = crc32(uint8);
        const size = uint8.length;

        // Local file header (30 bytes + filename)
        const localHeader = new Uint8Array(30 + nameBytes.length);
        const lv = new DataView(localHeader.buffer);

        lv.setUint32(0, 0x04034b50, true); // Local file header signature
        lv.setUint16(4, 10, true); // Version needed to extract
        lv.setUint16(6, 0, true); // General purpose bit flag
        lv.setUint16(8, 0, true); // Compression method (0 = store)
        lv.setUint16(10, 0, true); // Last mod file time
        lv.setUint16(12, 0, true); // Last mod file date
        lv.setUint32(14, crc, true); // CRC-32
        lv.setUint32(18, size, true); // Compressed size
        lv.setUint32(22, size, true); // Uncompressed size
        lv.setUint16(26, nameBytes.length, true); // File name length
        lv.setUint16(28, 0, true); // Extra field length
        localHeader.set(nameBytes, 30);

        fileEntries.push({
            nameBytes,
            crc,
            size,
            offset
        });

        parts.push(localHeader);
        parts.push(uint8);
        offset += localHeader.length + size;
    }

    const centralDirStart = offset;
    let centralDirSize = 0;

    for (const entry of fileEntries) {
        // Central directory file header (46 bytes + filename)
        const cHeader = new Uint8Array(46 + entry.nameBytes.length);
        const cv = new DataView(cHeader.buffer);

        cv.setUint32(0, 0x02014b50, true); // Central file header signature
        cv.setUint16(4, 20, true); // Version made by
        cv.setUint16(6, 10, true); // Version needed to extract
        cv.setUint16(8, 0, true); // General purpose bit flag
        cv.setUint16(10, 0, true); // Compression method (0 = store)
        cv.setUint16(12, 0, true); // Last mod file time
        cv.setUint16(14, 0, true); // Last mod file date
        cv.setUint32(16, entry.crc, true); // CRC-32
        cv.setUint32(20, entry.size, true); // Compressed size
        cv.setUint24 ? cv.setUint32(24, entry.size, true) : cv.setUint32(24, entry.size, true); // Uncompressed size
        cv.setUint16(28, entry.nameBytes.length, true); // File name length
        cv.setUint16(30, 0, true); // Extra field length
        cv.setUint16(32, 0, true); // File comment length
        cv.setUint16(34, 0, true); // Disk number start
        cv.setUint16(36, 0, true); // Internal file attributes
        cv.setUint32(38, 0, true); // External file attributes
        cv.setUint32(42, entry.offset, true); // Relative offset of local header
        cHeader.set(entry.nameBytes, 46);

        parts.push(cHeader);
        centralDirSize += cHeader.length;
    }

    // End of central directory record (22 bytes)
    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true); // EOCD signature
    ev.setUint16(4, 0, true); // Number of this disk
    ev.setUint16(6, 0, true); // Disk where central directory starts
    ev.setUint16(8, fileEntries.length, true); // Number of central directory records on this disk
    ev.setUint16(10, fileEntries.length, true); // Total number of central directory records
    ev.setUint32(12, centralDirSize, true); // Size of central directory
    ev.setUint32(16, centralDirStart, true); // Offset of start of central directory
    ev.setUint16(20, 0, true); // ZIP file comment length

    parts.push(eocd);

    return new Blob(parts, { type: 'application/zip' });
}
