/**
 * BatchQueueManager - Quản lý hàng đợi và điều phối xử lý song song nhiều video/ảnh
 */
export class BatchQueueManager {
    constructor(options = {}) {
        this.concurrency = Math.max(1, Math.min(8, options.concurrency || 2));
        this.tasks = new Map(); // id -> Task
        this.runningCount = 0;
        this.isRunning = false;
        this.processor = options.processor || null; // async function(file, options)

        // Event callbacks
        this.onTaskAdd = options.onTaskAdd || (() => {});
        this.onTaskUpdate = options.onTaskUpdate || (() => {});
        this.onTaskProgress = options.onTaskProgress || (() => {});
        this.onTaskComplete = options.onTaskComplete || (() => {});
        this.onTaskError = options.onTaskError || (() => {});
        this.onQueueDrain = options.onQueueDrain || (() => {});
        this.onStatsChange = options.onStatsChange || (() => {});
    }

    setConcurrency(value) {
        this.concurrency = Math.max(1, Math.min(8, Number(value) || 2));
        if (this.isRunning) {
            this._scheduleNext();
        }
    }

    setProcessor(fn) {
        this.processor = fn;
    }

    addTask(file, customOptions = {}) {
        const id = `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        const task = {
            id,
            file,
            name: file.name || 'unnamed_video.mp4',
            size: file.size || 0,
            type: file.type || 'video/mp4',
            status: 'pending', // 'pending' | 'processing' | 'completed' | 'failed' | 'canceled'
            progress: 0,
            processedFrames: 0,
            frameEstimate: 0,
            elapsedSeconds: 0,
            speedFps: 0,
            error: null,
            resultBlob: null,
            resultUrl: null,
            resultMeta: null,
            options: { ...customOptions },
            createdAt: Date.now(),
            startedAt: null,
            completedAt: null
        };

        this.tasks.set(id, task);
        this.onTaskAdd(task);
        this._notifyStats();

        if (this.isRunning) {
            this._scheduleNext();
        }

        return task;
    }

    addFiles(files, defaultOptions = {}) {
        const added = [];
        for (const file of files) {
            if (file && (file.type?.startsWith('video/') || /\.(mp4|webm|mov|m4v|mkv)$/i.test(file.name))) {
                added.push(this.addTask(file, defaultOptions));
            }
        }
        return added;
    }

    start() {
        this.isRunning = true;
        this._scheduleNext();
        this._notifyStats();
    }

    pause() {
        this.isRunning = false;
        this._notifyStats();
    }

    cancelTask(id) {
        const task = this.tasks.get(id);
        if (!task) return;

        if (task.status === 'processing') {
            task.abortController?.abort();
            task.status = 'canceled';
            this.runningCount = Math.max(0, this.runningCount - 1);
            this.onTaskUpdate(task);
            this._scheduleNext();
        } else if (task.status === 'pending') {
            task.status = 'canceled';
            this.onTaskUpdate(task);
        }
        this._notifyStats();
    }

    retryTask(id) {
        const task = this.tasks.get(id);
        if (!task) return;

        if (task.status === 'failed' || task.status === 'canceled') {
            if (task.resultUrl) {
                URL.revokeObjectURL(task.resultUrl);
                task.resultUrl = null;
            }
            task.status = 'pending';
            task.progress = 0;
            task.error = null;
            task.resultBlob = null;
            task.resultMeta = null;
            this.onTaskUpdate(task);
            if (this.isRunning) {
                this._scheduleNext();
            }
            this._notifyStats();
        }
    }

    removeTask(id) {
        const task = this.tasks.get(id);
        if (!task) return;

        if (task.status === 'processing') {
            this.cancelTask(id);
        }
        if (task.resultUrl) {
            URL.revokeObjectURL(task.resultUrl);
        }
        this.tasks.delete(id);
        this.onTaskUpdate({ id, _removed: true });
        this._notifyStats();
    }

    clearCompleted() {
        for (const [id, task] of this.tasks.entries()) {
            if (task.status === 'completed' || task.status === 'canceled') {
                if (task.resultUrl) {
                    URL.revokeObjectURL(task.resultUrl);
                }
                this.tasks.delete(id);
            }
        }
        this._notifyStats();
    }

    clearAll() {
        for (const [id, task] of this.tasks.entries()) {
            if (task.status === 'processing') {
                task.abortController?.abort();
            }
            if (task.resultUrl) {
                URL.revokeObjectURL(task.resultUrl);
            }
        }
        this.tasks.clear();
        this.runningCount = 0;
        this._notifyStats();
    }

    getStats() {
        let total = 0;
        let pending = 0;
        let processing = 0;
        let completed = 0;
        let failed = 0;
        let canceled = 0;
        let totalProgressSum = 0;

        for (const task of this.tasks.values()) {
            total++;
            if (task.status === 'pending') pending++;
            else if (task.status === 'processing') {
                processing++;
                totalProgressSum += task.progress || 0;
            } else if (task.status === 'completed') {
                completed++;
                totalProgressSum += 1;
            } else if (task.status === 'failed') failed++;
            else if (task.status === 'canceled') canceled++;
        }

        const overallProgress = total > 0 ? (totalProgressSum / total) : 0;

        return {
            total,
            pending,
            processing,
            completed,
            failed,
            canceled,
            isRunning: this.isRunning,
            concurrency: this.concurrency,
            overallProgress
        };
    }

    _notifyStats() {
        this.onStatsChange(this.getStats());
    }

    _scheduleNext() {
        if (!this.isRunning) return;

        while (this.runningCount < this.concurrency) {
            // Find next pending task
            let nextTask = null;
            for (const task of this.tasks.values()) {
                if (task.status === 'pending') {
                    nextTask = task;
                    break;
                }
            }

            if (!nextTask) {
                // No more pending tasks
                if (this.runningCount === 0) {
                    this.onQueueDrain();
                }
                break;
            }

            this._runTask(nextTask);
        }
    }

    async _runTask(task) {
        if (!this.processor) {
            console.error('BatchQueueManager: No processor function assigned.');
            return;
        }

        this.runningCount++;
        task.status = 'processing';
        task.startedAt = Date.now();
        task.abortController = new AbortController();
        this.onTaskUpdate(task);
        this._notifyStats();

        let lastFrameCount = 0;
        let lastFrameTime = Date.now();

        const progressReporter = (progressData) => {
            if (task.status !== 'processing') return;

            const now = Date.now();
            const timeDelta = (now - lastFrameTime) / 1000;
            if (timeDelta >= 0.5 && progressData.processedFrames) {
                const frameDelta = progressData.processedFrames - lastFrameCount;
                task.speedFps = Math.max(0, Math.round(frameDelta / timeDelta));
                lastFrameCount = progressData.processedFrames;
                lastFrameTime = now;
            }

            task.progress = progressData.progress || 0;
            task.processedFrames = progressData.processedFrames || 0;
            task.frameEstimate = progressData.frameEstimate || 0;
            task.elapsedSeconds = progressData.elapsedSeconds || 0;

            this.onTaskProgress(task, progressData);
            this.onTaskUpdate(task);
            this._notifyStats();
        };

        try {
            const result = await this.processor(task.file, {
                ...task.options,
                abortSignal: task.abortController.signal,
                onProgress: progressReporter
            });

            if (task.status === 'canceled') {
                return;
            }

            task.status = 'completed';
            task.progress = 1;
            task.completedAt = Date.now();
            task.resultBlob = result.blob || null;
            task.resultMeta = result.metadata || null;
            if (result.blob) {
                task.resultUrl = URL.createObjectURL(result.blob);
            }

            this.onTaskComplete(task, result);
        } catch (err) {
            if (task.status === 'canceled') {
                return;
            }
            console.error(`Task ${task.name} failed:`, err);
            task.status = 'failed';
            task.error = err.message || String(err);
            this.onTaskError(task, err);
        } finally {
            if (task.status === 'processing') {
                this.runningCount = Math.max(0, this.runningCount - 1);
            } else if (task.status === 'completed' || task.status === 'failed') {
                this.runningCount = Math.max(0, this.runningCount - 1);
            }
            this.onTaskUpdate(task);
            this._notifyStats();
            this._scheduleNext();
        }
    }
}
