function setStatus(message, tone = 'info') {
    if (els.status) {
        els.status.textContent = message || '';
        els.status.dataset.tone = tone;
    }
}

async function ensureAllenkFdncnnRuntime({ backend = 'wasm', detection = null } = {}) {
    const profile = resolveAllenkFdncnnRuntimeProfile(detection?.position);
    const key = `${backend}:${profile.profileKey}`;
    if (!allenkFdncnnRuntimePromises.has(key)) {
        allenkFdncnnRuntimePromises.set(key, (async () => {
            const ort = await import('onnxruntime-web');
            const wasmPaths = backend === 'webgpu' ? ALLENK_FDNCNN_WEBGPU_WASM_PATHS : ALLENK_FDNCNN_WASM_PATHS;
            ort.env.wasm.wasmPaths = wasmPaths;
            return await createAllenkFdncnnOnnxRuntime({
                ort,
                backend,
                modelPath: profile.modelPath,
                inputName: profile.inputName,
                outputName: profile.outputName,
                roiShape: profile.roiShape,
                sigma: profile.sigma,
                padding: profile.padding,
                temporalReuse: profile.temporalReuse
            });
        })().catch((err) => {
            allenkFdncnnRuntimePromises.delete(key);
            throw err;
        }));
    }
    return await allenkFdncnnRuntimePromises.get(key);
}

let selectedDirectoryHandle = null;

async function saveFileDirectlyOrDownload(blob, filename) {
    if (selectedDirectoryHandle) {
        try {
            const fileHandle = await selectedDirectoryHandle.getFileHandle(filename, { create: true });
            const writable = await fileHandle.createWritable();
            await writable.write(blob);
            await writable.close();
            console.log(`[Directory] Đã lưu ngầm file ${filename} vào thư mục`);
            return true;
        } catch (err) {
            console.warn('Lỗi ghi trực tiếp vào thư mục (fallback sang tải trình duyệt):', err);
        }
    }
    triggerFileDownload(blob, filename);
    return false;
}

const queueManager = new BatchQueueManager({
    concurrency: 2,
    processor: async (file, options) => {
        const denoiseBackend = options.denoiseBackend || 'allenk-fdncnn-browser-spike';
        let allenkFdncnnRuntime = null;

        if (denoiseBackend === 'allenk-fdncnn-browser-spike') {
            try {
                allenkFdncnnRuntime = await ensureAllenkFdncnnRuntime({ backend: 'wasm' });
            } catch (err) {
                console.warn('FDnCNN runtime initialization fallback:', err);
            }
        }

        const videoBitrate = (Number(options.bitrateMbps) || 12) * 1_000_000;

        const result = await removeGeminiVideoWatermark(file, {
            denoiseBackend,
            allenkFdncnnRuntime,
            videoBitrate,
            adaptiveAlpha: Boolean(options.adaptiveAlpha),
            allowLowConfidence: Boolean(options.allowLowConfidence),
            onProgress: (prog) => {
                if (options.onProgress) {
                    options.onProgress(prog);
                }
            }
        });

        return result;
    },
    onTaskAdd: (task) => {
        renderQueue();
    },
    onTaskUpdate: (task) => {
        updateTaskItemElement(task);
    },
    onTaskComplete: async (task, result) => {
        updateTaskItemElement(task);
        if (els.autoDownloadCheck && els.autoDownloadCheck.checked && task.resultBlob) {
            await saveFileDirectlyOrDownload(task.resultBlob, `[clean]_${task.name}`);
        }
    },
    onStatsChange: (stats) => {
        renderStats(stats);
    }
});

function triggerFileDownload(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }, 1000);
}

// Render Stats in UI
function renderStats(stats) {
    if (els.statTotal) els.statTotal.textContent = stats.total;
    if (els.statProcessing) els.statProcessing.textContent = stats.processing;
    if (els.statCompleted) els.statCompleted.textContent = stats.completed;
    if (els.statOverallProgress) {
        els.statOverallProgress.textContent = `${Math.round(stats.overallProgress * 100)}%`;
    }
    if (els.queueCountBadge) {
        els.queueCountBadge.textContent = stats.total;
    }

    if (els.startAllBtn) {
        els.startAllBtn.disabled = stats.isRunning || stats.pending === 0;
    }
    if (els.pauseAllBtn) {
        els.pauseAllBtn.disabled = !stats.isRunning;
    }
    if (els.downloadAllZipBtn) {
        els.downloadAllZipBtn.disabled = stats.completed === 0;
    }
}

// Render the entire Queue List
function renderQueue() {
    if (!els.queueList) return;

    if (queueManager.tasks.size === 0) {
        els.queueList.innerHTML = '';
        if (els.queueEmpty) {
            els.queueList.appendChild(els.queueEmpty);
            els.queueEmpty.style.display = 'flex';
        }
        return;
    }

    if (els.queueEmpty) {
        els.queueEmpty.style.display = 'none';
    }

    const existingIds = new Set(Array.from(els.queueList.children).map(el => el.dataset.taskId));
    for (const [id, task] of queueManager.tasks.entries()) {
        if (!existingIds.has(id)) {
            const itemEl = createQueueItemElement(task);
            els.queueList.appendChild(itemEl);
        } else {
            updateTaskItemElement(task);
        }
    }
}

function createQueueItemElement(task) {
    const el = document.createElement('div');
    el.className = 'queue-item';
    el.dataset.taskId = task.id;

    el.innerHTML = `
        <div class="item-icon">🎬</div>
        <div class="item-info">
            <div class="item-name" title="${task.name}">${task.name}</div>
            <div class="item-meta">
                <span>${formatBytes(task.size)}</span>
                <span class="item-speed" style="color: var(--primary);"></span>
            </div>
        </div>
        <div class="item-progress-col">
            <div class="item-progress-bar">
                <div class="fill" style="width: 0%;"></div>
            </div>
            <div class="item-progress-text">
                <span class="pct">0%</span>
                <span class="frames">0 / 0 frames</span>
            </div>
        </div>
        <div>
            <span class="status-badge pending">Chờ xử lý</span>
        </div>
        <div class="item-actions">
            <button class="icon-btn inspect-btn" title="Xem & So sánh Video" type="button">🔍</button>
            <button class="icon-btn download-one" title="Tải về" type="button" disabled>⬇️</button>
            <button class="icon-btn remove-btn" title="Xoá" type="button">✕</button>
        </div>
    `;

    // Event listeners
    el.querySelector('.inspect-btn').addEventListener('click', () => {
        loadTaskIntoSingleInspector(task);
    });

    el.querySelector('.download-one').addEventListener('click', () => {
        if (task.resultBlob) {
            triggerFileDownload(task.resultBlob, `[clean]_${task.name}`);
        }
    });

    el.querySelector('.remove-btn').addEventListener('click', () => {
        queueManager.removeTask(task.id);
        el.remove();
        if (queueManager.tasks.size === 0 && els.queueEmpty) {
            els.queueList.appendChild(els.queueEmpty);
            els.queueEmpty.style.display = 'flex';
        }
    });

    return el;
}

function updateTaskItemElement(task) {
    if (!els.queueList) return;
    if (task._removed) {
        const item = els.queueList.querySelector(`[data-task-id="${task.id}"]`);
        if (item) item.remove();
        return;
    }

    const el = els.queueList.querySelector(`[data-task-id="${task.id}"]`);
    if (!el) return;

    const fill = el.querySelector('.fill');
    const pct = el.querySelector('.pct');
    const frames = el.querySelector('.frames');
    const badge = el.querySelector('.status-badge');
    const speed = el.querySelector('.item-speed');
    const dlBtn = el.querySelector('.download-one');
    const progressBar = el.querySelector('.item-progress-bar');

    const progressPct = Math.round((task.progress || 0) * 100);
    if (fill) fill.style.width = `${progressPct}%`;
    if (pct) pct.textContent = `${progressPct}%`;
    if (frames && task.frameEstimate) {
        frames.textContent = `${task.processedFrames} / ${task.frameEstimate} frames`;
    }

    if (speed) {
        if (task.status === 'processing' && task.speedFps > 0) {
            speed.textContent = `• ${task.speedFps} fps`;
        } else {
            speed.textContent = '';
        }
    }

    if (badge) {
        badge.className = `status-badge ${task.status}`;
        switch (task.status) {
            case 'pending': badge.textContent = 'Chờ xử lý'; break;
            case 'processing': badge.textContent = 'Đang xử lý'; break;
            case 'completed': badge.textContent = 'Hoàn thành'; break;
            case 'failed': badge.textContent = 'Lỗi'; break;
            case 'canceled': badge.textContent = 'Đã huỷ'; break;
        }
    }

    if (progressBar) {
        progressBar.className = `item-progress-bar ${task.status}`;
    }

    if (dlBtn) {
        dlBtn.disabled = task.status !== 'completed' || !task.resultBlob;
    }
}

function loadTaskIntoSingleInspector(task) {
    // Switch to single tab
    switchTab('single');
    loadVideoFile(task.file);

    if (task.resultBlob) {
        // Also show processed video
        if (singleState.processedUrl) {
            URL.revokeObjectURL(singleState.processedUrl);
        }
        singleState.processedUrl = URL.createObjectURL(task.resultBlob);
        els.processedVideo.src = singleState.processedUrl;
        els.processedEmpty.hidden = true;
        els.afterBadge.hidden = false;
        els.downloadBtn.removeAttribute('aria-disabled');
        els.downloadBtn.href = singleState.processedUrl;
        els.downloadBtn.download = `[clean]_${task.name}`;
        setStatus('Đã nạp kết quả xử lý của video từ hàng đợi.', 'success');
    }
}

function switchTab(mode) {
    if (mode === 'batch') {
        els.tabBatchBtn.classList.add('active');
        els.tabSingleBtn.classList.remove('active');
        els.batchView.classList.add('active');
        els.singleView.classList.remove('active');
    } else {
        els.tabSingleBtn.classList.add('active');
        els.tabBatchBtn.classList.remove('active');
        els.singleView.classList.add('active');
        els.batchView.classList.remove('active');
    }
}

