els.downloadAllZipBtn?.addEventListener('click', async () => {
    const completedTasks = Array.from(queueManager.tasks.values()).filter(t => t.status === 'completed' && t.resultBlob);
    if (completedTasks.length === 0) return;

    els.downloadAllZipBtn.disabled = true;
    els.downloadAllZipBtn.textContent = 'Đang nén ZIP...';

    try {
        const filesToZip = completedTasks.map(t => ({
            name: `[clean]_${t.name}`,
            data: t.resultBlob
        }));

        const zipBlob = await createZipBlob(filesToZip);
        triggerFileDownload(zipBlob, `Gemini_Cleaned_Videos_${new Date().toISOString().slice(0, 10)}.zip`);
    } catch (err) {
        console.error('Failed to create ZIP:', err);
        alert('Lỗi tạo file ZIP: ' + err.message);
    } finally {
        els.downloadAllZipBtn.disabled = false;
        els.downloadAllZipBtn.textContent = '📦 Tải về Tất cả (.ZIP)';
    }
});

// Dropzone & File input
els.dropzone?.addEventListener('click', () => els.fileInput?.click());
els.dropzone?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        els.fileInput?.click();
    }
});

['dragenter', 'dragover'].forEach(name => {
    els.dropzone?.addEventListener(name, (e) => {
        e.preventDefault();
        els.dropzone.dataset.dragging = 'true';
    });
});

['dragleave', 'drop'].forEach(name => {
    els.dropzone?.addEventListener(name, (e) => {
        e.preventDefault();
        els.dropzone.dataset.dragging = 'false';
    });
});

els.dropzone?.addEventListener('drop', (e) => {
    const files = Array.from(e.dataTransfer?.files || []);
    handleFilesInput(files);
});

els.fileInput?.addEventListener('change', (e) => {
    const files = Array.from(e.target.files || []);
    handleFilesInput(files);
    els.fileInput.value = '';
});

async function handleFilesInput(files) {
    if (!files || files.length === 0) return;

    // Check if user uploaded image files
    const firstFile = files[0];
    if (firstFile.type?.startsWith('image/')) {
        try {
            await saveDebugFileHandoff(firstFile, 'image');
            window.location.href = './dev-preview.html?fileHandoff=1';
        } catch (err) {
            console.error('Lỗi chuyển tiếp file ảnh:', err);
            window.location.href = './dev-preview.html';
        }
        return;
    }

    const batchOptions = {
        denoiseBackend: els.batchDenoiseBackend?.value || 'allenk-fdncnn-browser-spike',
        bitrateMbps: Number(els.batchBitrate?.value) || 12,
        adaptiveAlpha: Boolean(els.batchAdaptiveAlphaCheck?.checked),
        allowLowConfidence: Boolean(els.batchAllowLowConfidenceCheck?.checked)
    };

    queueManager.addFiles(files, batchOptions);
    renderQueue();

    // If 1 file was added, load it into inspector as well
    if (files.length === 1) {
        loadVideoFile(files[0]);
    }
}

