function renderMetadata(meta) {
    if (!els.metadata) return;
    if (!meta) {
        els.metadata.innerHTML = '<div style="padding: 16px 20px; color: var(--text-dim);">Chưa có video</div>';
        return;
    }
    const isReference = isReferenceGeminiVideoSize({ width: meta.width, height: meta.height });
    els.metadata.innerHTML = `
        <dl>
            <div><dt>Độ phân giải</dt><dd>${meta.width} × ${meta.height} ${isReference ? '<span style="color: var(--accent);">(Gemini Chuẩn)</span>' : ''}</dd></div>
            <div><dt>Thời lượng</dt><dd>${formatDuration(meta.duration)} (${meta.duration?.toFixed(2)}s)</dd></div>
            <div><dt>Tốc độ khung</dt><dd>${meta.frameRate?.toFixed(2)} fps</dd></div>
            <div><dt>Ước tính frames</dt><dd>${meta.frameCountEstimate || 'N/A'}</dd></div>
            <div><dt>Codec Video</dt><dd>${meta.codec || 'AVC'}</dd></div>
        </dl>
    `;
}

function renderDetection(detection) {
    if (!els.detection) return;
    if (!detection) {
        els.detection.innerHTML = '<div style="padding: 16px 20px; color: var(--text-dim);">Chưa kiểm tra toạ độ</div>';
        return;
    }
    const p = detection.position;
    els.detection.innerHTML = `
        <dl>
            <div><dt>Vị trí X, Y</dt><dd>${p.x}, ${p.y}</dd></div>
            <div><dt>Kích thước</dt><dd>${p.width} × ${p.height} px</dd></div>
            <div><dt>Độ tin cậy</dt><dd style="color: var(--primary); font-weight: bold;">${(detection.confidence * 100).toFixed(1)}%</dd></div>
            <div><dt>Loại Watermark</dt><dd>${detection.candidate?.id || 'Veo / Gemini Watermark'}</dd></div>
        </dl>
    `;
}

async function loadVideoFile(file) {
    singleState.file = file;
    if (singleState.originalUrl) URL.revokeObjectURL(singleState.originalUrl);
    if (singleState.processedUrl) URL.revokeObjectURL(singleState.processedUrl);

    singleState.originalUrl = URL.createObjectURL(file);
    singleState.processedUrl = null;
    singleState.metadata = null;
    singleState.detection = null;

    els.originalVideo.src = singleState.originalUrl;
    els.processedVideo.src = '';
    els.originalEmpty.hidden = true;
    els.processedEmpty.hidden = false;
    els.afterBadge.hidden = true;
    els.downloadBtn.setAttribute('aria-disabled', 'true');
    els.downloadBtn.removeAttribute('href');
    if (els.progressBar) els.progressBar.style.width = '0%';
    if (els.progressText) els.progressText.textContent = file.name;

    setStatus('Đang kiểm tra metadata video...', 'info');

    try {
        const meta = await inspectGeminiVideoFile(file);
        singleState.metadata = meta;
        renderMetadata(meta);
        setStatus('Đã tải video. Sẵn sàng xử lý!', 'success');
        els.playPauseBtn.disabled = false;
        els.scrubber.disabled = false;
    } catch (err) {
        console.error('Failed to inspect video:', err);
        setStatus(`Lỗi đọc video: ${err.message}`, 'error');
    }
}

// Playback Sync
function syncPlay() {
    els.originalVideo.play().catch(() => {});
    if (singleState.processedUrl) {
        els.processedVideo.play().catch(() => {});
    }
    els.playPauseBtn.dataset.playing = 'true';
}

function syncPause() {
    els.originalVideo.pause();
    if (singleState.processedUrl) {
        els.processedVideo.pause();
    }
    els.playPauseBtn.dataset.playing = 'false';
}

els.playPauseBtn?.addEventListener('click', () => {
    if (els.originalVideo.paused) {
        syncPlay();
    } else {
        syncPause();
    }
});

els.originalVideo?.addEventListener('timeupdate', () => {
    if (singleState.syncingPlayback) return;
    const dur = singleState.metadata?.duration || els.originalVideo.duration || 1;
    const curr = els.originalVideo.currentTime;
    if (els.scrubber) els.scrubber.value = String((curr / dur) * 1000);
    if (els.timeLabel) els.timeLabel.textContent = `${formatDuration(curr)} / ${formatDuration(dur)}`;

    if (singleState.processedUrl && Math.abs(els.processedVideo.currentTime - curr) > 0.1) {
        els.processedVideo.currentTime = curr;
    }
});

els.scrubber?.addEventListener('input', (e) => {
    const dur = singleState.metadata?.duration || els.originalVideo.duration || 1;
    const time = (Number(e.target.value) / 1000) * dur;
    singleState.syncingPlayback = true;
    els.originalVideo.currentTime = time;
    if (singleState.processedUrl) els.processedVideo.currentTime = time;
    if (els.timeLabel) els.timeLabel.textContent = `${formatDuration(time)} / ${formatDuration(dur)}`;
    singleState.syncingPlayback = false;
});

// Single Detect Button
els.detectBtn?.addEventListener('click', async () => {
    if (!singleState.file) {
        setStatus('Vui lòng chọn video trước.', 'warn');
        return;
    }
    setStatus('Đang quét toạ độ watermark...', 'info');
    try {
        const detection = await detectGeminiVideoWatermark(singleState.file, {
            sampleCount: 12
        });
        singleState.detection = detection;
        renderDetection(detection);
        setStatus(`Đã tìm thấy watermark: ${(detection.confidence * 100).toFixed(1)}% tin cậy.`, 'success');
    } catch (err) {
        console.error('Detection failed:', err);
        setStatus(`Lỗi phát hiện: ${err.message}`, 'error');
    }
});

// Single Process Button
els.processBtn?.addEventListener('click', async () => {
    if (!singleState.file) {
        setStatus('Vui lòng chọn video trước.', 'warn');
        return;
    }
    if (singleState.running) return;

    singleState.running = true;
    els.processBtn.disabled = true;
    setStatus('Bắt đầu xử lý xoá watermark...', 'info');

    try {
        let allenkFdncnnRuntime = null;
        try {
            allenkFdncnnRuntime = await ensureAllenkFdncnnRuntime({ backend: 'wasm' });
        } catch (err) {
            console.warn('FDnCNN runtime initialization fallback:', err);
        }

        const result = await removeGeminiVideoWatermark(singleState.file, {
            allenkFdncnnRuntime,
            denoiseBackend: 'allenk-fdncnn-browser-spike',
            videoBitrate: 12_000_000,
            onProgress: (prog) => {
                const pct = Math.round((prog.progress || 0) * 100);
                if (els.progressBar) els.progressBar.style.width = `${pct}%`;
                if (els.progressText) els.progressText.textContent = `${pct}% (${prog.processedFrames || 0} frames)`;
            }
        });

        if (singleState.processedUrl) URL.revokeObjectURL(singleState.processedUrl);
        singleState.processedUrl = URL.createObjectURL(result.blob);
        els.processedVideo.src = singleState.processedUrl;
        els.processedEmpty.hidden = true;
        els.afterBadge.hidden = false;
        els.downloadBtn.removeAttribute('aria-disabled');
        els.downloadBtn.href = singleState.processedUrl;
        els.downloadBtn.download = `[clean]_${singleState.file.name}`;
        setStatus('Hoàn thành! Bạn có thể xem so sánh hoặc tải về.', 'success');
    } catch (err) {
        console.error('Export failed:', err);
        setStatus(`Lỗi xuất video: ${err.message}`, 'error');
    } finally {
        singleState.running = false;
        els.processBtn.disabled = false;
    }
});

els.resetBtn?.addEventListener('click', () => {
    singleState.file = null;
    if (singleState.originalUrl) URL.revokeObjectURL(singleState.originalUrl);
    if (singleState.processedUrl) URL.revokeObjectURL(singleState.processedUrl);
    singleState.originalUrl = null;
    singleState.processedUrl = null;
    singleState.metadata = null;
    singleState.detection = null;
    els.originalVideo.src = '';
    els.processedVideo.src = '';
    els.originalEmpty.hidden = false;
    els.processedEmpty.hidden = false;
    els.afterBadge.hidden = true;
    renderMetadata(null);
    renderDetection(null);
    if (els.progressBar) els.progressBar.style.width = '0%';
    if (els.progressText) els.progressText.textContent = 'Chưa chọn video';
    setStatus('Đã làm mới', 'info');
});

// Check if any debug file handoff exists on page load
consumeDebugFileHandoff('video').then((record) => {
    if (record?.file) {
        handleFilesInput([record.file]);
    }
}).catch((err) => console.warn('video handoff error:', err));
